INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_010_M02_S01', 'Buoyancy', '1', 'Buoyancy refers to the net upward force exerted by a fluid on an immersed or floating body due to the pressure distribution in the fluid. In Hydrostatics, the focus is on archimedes'' principle, displaced-fluid volume, centre of buoyancy and floating equilibrium.', 'SSD_BUOYANCY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_010_M03_S01', 'Continuity', '1', 'Continuity refers to the mass-conservation relation requiring that mass entering, leaving and accumulating within a fluid system satisfy conservation of mass. In Kinematics, the focus is on control-volume continuity, steady/unsteady flow, incompressible simplification and area-velocity relationships.', 'SSD_CONTINUITY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_010_M04_S01', 'Reynolds number', '1', 'Reynolds number refers to a dimensionless ratio comparing inertial effects with viscous effects in fluid flow. In Dynamics, the focus is on re = ρVL/μ, characteristic length/velocity choices, similarity and flow-regime interpretation.', 'SSD_REYNOLDS_NUMBER', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_010_M05_S01', 'Head loss and pipe-flow analysis', '1', 'Head loss and pipe-flow analysis: Analysis of pressure or energy losses associated with fluid flow through pipes and fittings. In Pipe Flow, the focus is on darcy-Weisbach equation, friction factor, minor losses, hydraulic grade/energy lines and flow regimes.', 'SSD_HEAD_LOSS_AND_PIPE_FLOW_ANALYSIS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_011_M01_S01', 'Truss and beam analysis', '1', 'Truss and beam analysis: Structural analysis procedures for determining internal forces and reactions in idealized trusses and beams under applied loads. In Determinate Structures, the focus is on equilibrium, free-body diagrams, axial truss forces, shear and bending moment in beams.', 'SSD_TRUSS_AND_BEAM_ANALYSIS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_011_M02_S01', 'Moment-area theorem', '1', 'Moment-area theorem: Beam-deflection relations that connect changes in slope and deflection to areas and first moments of the M/EI diagram. In Deflections, the focus is on theorem 1 for slope change, theorem 2 for tangential deviation, boundary conditions and sign conventions.', 'SSD_MOMENT_AREA_THEOREM', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_011_M03_S01', 'Virtual work', '1', 'Virtual work refers to an analytical method that uses work equivalence under a compatible virtual displacement to determine structural responses. In Energy Methods, the focus is on virtual displacements, external/internal virtual work, unit-load method and displacement calculation.', 'SSD_VIRTUAL_WORK', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_011_M04_S01', 'Influence-line construction', '1', 'Influence-line construction refers to a graphical or analytical representation showing how a response quantity at a specified location varies as a moving load changes position. In Influence Lines, the focus is on influence lines for reactions, shear, moment and other responses in determinate structures.', 'SSD_INFLUENCE_LINE_CONSTRUCTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_011_M05_S01', 'Slope-deflection', '1', 'Slope-deflection refers to a displacement-based structural analysis method relating member end moments to end rotations, translations and fixed-end actions. In Indeterminate Structures, the focus is on member stiffness, end rotations, joint translations, fixed-end moments and compatibility equations.', 'SSD_SLOPE_DEFLECTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_012_M01_S01', 'Atterberg limits', '1', 'Atterberg limits: Empirical moisture-content limits used to characterize the consistency and plasticity range of fine-grained soils. In Soil Classification, the focus is on liquid limit, plastic limit, shrinkage limit, plasticity index and consistency states.', 'SSD_ATTERBERG_LIMITS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_012_M02_S01', 'Darcy''s law', '1', 'Darcy''s law refers to a constitutive relation stating that, under laminar saturated porous-media flow conditions, discharge is proportional to hydraulic gradient and hydraulic conductivity. In Permeability, the focus is on hydraulic head, gradient, hydraulic conductivity, discharge/flux and applicability limits.', 'SSD_DARCY_S_LAW', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_012_M03_S01', 'Consolidation settlement', '1', 'Consolidation settlement: Time-dependent settlement of a saturated or nearly saturated soil caused by dissipation of excess pore-water pressure and associated volume change under sustained loading. In Consolidation, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_CONSOLIDATION_SETTLEMENT', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_012_M04_S01', 'Mohr-Coulomb failure criterion', '1', 'Mohr-Coulomb failure criterion refers to a frictional failure criterion relating shear strength of soil or rock to effective normal stress, cohesion and friction angle. In Shear Strength, the focus is on τf = c'' + σ''n tanφ'' for effective-stress form, failure envelope and drained/undrained interpretation.', 'SSD_MOHR_COULOMB_FAILURE_CRITERION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_012_M05_S01', 'Lateral earth pressure', '1', 'Lateral earth pressure refers to the pressure exerted by soil against a retaining or embedded structure due to soil self-weight, surcharge, groundwater and other actions. In Earth Pressure, the focus is on active, passive and at-rest states, earth-pressure coefficients, wall friction and groundwater effects.', 'SSD_LATERAL_EARTH_PRESSURE', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_013_M01_S01', 'Demand forecasting', '1', 'Demand forecasting: Estimation of future demand for a resource or service from historical observations, explanatory variables, assumptions, and uncertainty, used to support planning and design. In Water Demand, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_DEMAND_FORECASTING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_013_M02_S01', 'Filtration', '1', 'Filtration refers to a water or wastewater treatment process that removes suspended or particulate matter by passing fluid through a porous filter medium. In Water Treatment, the focus is on media filtration, straining, adsorption contributions, head loss, backwashing and filtration performance.', 'SSD_FILTRATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_013_M03_S01', 'Sewer design', '1', 'Sewer design: Engineering design of sewer systems to collect and convey wastewater safely and reliably to treatment or disposal facilities. In Wastewater Collection, the focus is on flow estimation, pipe sizing, hydraulic grade, self-cleansing considerations, minimum/maximum velocities and system layout.', 'SSD_SEWER_DESIGN', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_013_M04_S01', 'Activated sludge process', '1', 'Activated sludge process refers to a suspended-growth biological wastewater-treatment process in which microorganisms oxidize biodegradable pollutants in an aerated reactor followed by solids separation. In Sewage Treatment, the focus is on aeration, biomass concentration, substrate removal, secondary clarification, sludge age and return/waste activated sludge.', 'SSD_ACTIVATED_SLUDGE_PROCESS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_013_M05_S01', 'Solid-waste management', '1', 'Solid-waste management refers to the systematic handling of solid wastes through generation reduction, segregation, collection, transport, processing, recovery and final disposal. In Solid Waste, the focus is on waste characterization, collection, recycling/material recovery, biological treatment, thermal treatment and engineered disposal.', 'SSD_SOLID_WASTE_MANAGEMENT', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_014_M01_S01', 'Sight distance', '1', 'Sight distance refers to the roadway length over which a driver can see an object or roadway feature sufficiently far ahead to perform a required manoeuvre safely. In Highway Planning, the focus is on stopping, passing and decision sight distance; driver perception-reaction, speed, grade and geometric constraints.', 'SSD_SIGHT_DISTANCE', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_014_M02_S01', 'Super elevation', '1', 'Super elevation refers to the transverse slope provided on a roadway curve to assist in counteracting lateral acceleration associated with vehicle motion. In Geometric Design, the focus is on superelevation rate, side friction, design speed, radius, runoff and transition.', 'SSD_SUPER_ELEVATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_014_M03_S01', 'Traffic flow and control', '1', 'Traffic flow and control: Analysis and management of the movement of vehicles and people on transportation networks using flow relationships and control strategies. In Traffic Engineering, the focus is on flow, speed, density, fundamental diagrams, intersections, signals, capacity and control measures.', 'SSD_TRAFFIC_FLOW_AND_CONTROL', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_014_M04_S01', 'Bitumen testing', '1', 'Bitumen testing: Laboratory characterization of bituminous binders through standardized tests of consistency, viscosity, temperature susceptibility and related properties. In Pavement Materials, the focus is on penetration, ductility, softening point, viscosity, flash/fire point and temperature susceptibility, as applicable to the specification.', 'SSD_BITUMEN_TESTING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_014_M05_S01', 'Flexible pavement design', '1', 'Flexible pavement design: Design of layered pavement systems in which wheel loads are distributed through bituminous and granular layers over the subgrade. In Pavement Design, the focus is on traffic loading, material properties, layer thicknesses, subgrade strength, drainage, fatigue and rutting considerations.', 'SSD_FLEXIBLE_PAVEMENT_DESIGN', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_015_M01_S01', 'Gantt charts', '1', 'Gantt charts refers to a time-scaled project scheduling representation showing activities, durations and their planned timing. In Project Lifecycle, the focus is on activities, durations, start/finish dates, overlaps, milestones and progress tracking.', 'SSD_GANTT_CHARTS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_015_M02_S01', 'Crashing', '1', 'Crashing refers to a schedule-compression technique that reduces activity durations by applying additional resources or cost, subject to technical feasibility. In Network Techniques (CPM/PERT), the focus is on normal/crash durations and costs, cost slopes, critical paths and incremental time-cost trade-offs.', 'SSD_CRASHING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_015_M03_S01', 'Resource levelling', '1', 'Resource levelling refers to a scheduling process that adjusts activity timing to resolve resource over-allocation while respecting stated project constraints. In Resource Allocation, the focus is on resource availability, activity priorities, float, sequencing and schedule impacts.', 'SSD_RESOURCE_LEVELLING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_015_M04_S01', 'Depreciation and cost control', '1', 'Depreciation and cost control: Methods for allocating the depreciable cost of assets over their useful lives and monitoring project costs against budgets. In Cost Control, the focus is on straight-line and declining-balance methods, book value, useful life, residual value, cost variance and budget control.', 'SSD_DEPRECIATION_AND_COST_CONTROL', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_015_M05_S01', 'Equipment selection and productivity', '1', 'Equipment selection and productivity: Selection and operational assessment of construction equipment based on required work, capacity, cycle time, site conditions and economic constraints. In Construction Equipment, the focus is on equipment capacity, cycle time, utilization, production rate, operating cost and site compatibility.', 'SSD_EQUIPMENT_SELECTION_AND_PRODUCTIVITY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_016_M01_S01', 'Errors', '1', 'Errors: Deviations of measured or computed quantities from an accepted reference or true/accepted value, including systematic and random components. In Basics of Surveying, the focus is on accuracy, precision, systematic/random error, propagation, uncertainty and error detection.', 'SSD_ERRORS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_016_M02_S01', 'Benchmarks', '1', 'Benchmarks: Reference points with known or established elevations used to control vertical surveying and transfer elevation information. In Leveling & Contouring, the focus is on permanent/temporary benchmarks, datum, reduced levels, levelling networks and monumentation.', 'SSD_BENCHMARKS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_016_M03_S01', 'Angular measurement', '1', 'Angular measurement: Determination of horizontal or vertical angles between survey lines or directions using appropriate angular-measurement instruments. In Theodolite Surveying, the focus is on theodolites/total stations, centering, face observations, repetition, direction measurement and error control.', 'SSD_ANGULAR_MEASUREMENT', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_016_M04_S01', 'Horizontal and vertical curves', '1', 'Horizontal and vertical curves: Geometric transition elements used to connect roadway alignments while controlling changes in direction and grade. In Curves, the focus is on simple/compound horizontal curves, circular elements, transition curves, vertical parabolic curves and sight-distance considerations.', 'SSD_HORIZONTAL_AND_VERTICAL_CURVES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_016_M05_S01', 'GNSS/GPS and GIS applications', '1', 'GNSS/GPS and GIS applications: Use of satellite-based positioning and geographic information systems to acquire, reference, manage, analyze and visualize spatial data. In Modern Surveying (GPS/GIS), the focus is on gNSS positioning, coordinate reference systems, accuracy/error sources, GIS layers, spatial queries and mapping.', 'SSD_GNSS_GPS_AND_GIS_APPLICATIONS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_017_M01_S01', 'Control volumes', '1', 'Control volumes refers to a defined region in space used for applying conservation equations to mass, momentum, and energy crossing its boundary. In Basic Concepts, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_CONTROL_VOLUMES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_017_M02_S01', 'Energy equation', '1', 'Energy equation refers to a statement of energy conservation applied to a thermodynamic system or control volume. In First Law, the focus is on internal, kinetic and potential energy, heat transfer, work, mass-flow energy and steady-flow simplifications.', 'SSD_ENERGY_EQUATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_017_M03_S01', 'Second-law analysis', '1', 'Second-law analysis: Thermodynamic analysis based on the second law, including entropy balance and restrictions on energy-conversion processes. In Second Law, the focus is on entropy balance, irreversibility, entropy generation, reversible/irreversible processes and efficiency limits.', 'SSD_SECOND_LAW_ANALYSIS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_017_M04_S01', 'Entropy generation', '1', 'Entropy generation refers to the production of entropy associated with irreversible processes within a system or control volume. In Entropy, the focus is on entropy balance, heat transfer across finite temperature differences, friction, mixing and other irreversibilities.', 'SSD_ENTROPY_GENERATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_017_M05_S01', 'Carnot cycle', '1', 'Carnot cycle refers to an ideal reversible heat-engine cycle consisting of two isothermal and two reversible adiabatic (isentropic) processes between two thermal reservoirs. In Gas Power Cycles, the focus is on isothermal expansion/compression, isentropic expansion/compression and maximum reversible efficiency.', 'SSD_CARNOT_CYCLE', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_018_M01_S01', 'Velocity and acceleration fields', '1', 'Velocity and acceleration fields: Spatial and temporal fields describing fluid-particle velocity and acceleration throughout a flow domain. In Fluid Kinematics, the focus is on eulerian velocity field, material acceleration, local and convective acceleration, streamlines.', 'SSD_VELOCITY_AND_ACCELERATION_FIELDS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_018_M02_S01', 'Navier-Stokes equation', '1', 'Navier-Stokes equation refers to the momentum-conservation equation for a continuum fluid, with terms determined by density, pressure, body forces and constitutive behaviour. In Conservation Laws, the focus is on continuity coupling, pressure, viscous stresses, body forces, incompressible simplifications and boundary conditions.', 'SSD_NAVIER_STOKES_EQUATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_018_M03_S01', 'Boundary layers', '1', 'Boundary layers: Thin regions adjacent to solid surfaces in which viscous effects produce strong velocity gradients and influence momentum, heat, or mass transfer. In Viscous Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_BOUNDARY_LAYERS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_018_M04_S01', 'Pelton and Francis turbines', '1', 'Pelton and Francis turbines: Hydraulic turbine types represented by Pelton impulse turbines and Francis reaction turbines for converting water energy into shaft power. In Hydraulic Turbines, the focus is on pelton jet/bucket interaction; Francis runner, pressure change, head, flow rate, efficiency and operating range.', 'SSD_PELTON_AND_FRANCIS_TURBINES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_018_M05_S01', 'Centrifugal pumps', '1', 'Centrifugal pumps: Rotodynamic pumps that impart energy to a fluid primarily through the action of a rotating impeller, converting mechanical energy into fluid pressure and head. In Pumps, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_CENTRIFUGAL_PUMPS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_019_M01_S01', 'Grashof''s law', '1', 'Grashof''s law refers to a kinematic criterion for planar four-bar linkages relating link lengths to the possibility of continuous rotation of at least one link. In Mechanisms, the focus is on shortest/longest/other link lengths, S+L ≤ P+Q criterion and limiting cases.', 'SSD_GRASHOF_S_LAW', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_019_M02_S01', 'Instantaneous centers', '1', 'Instantaneous centers: Points or centers in planar rigid-body motion about which the relative velocity between two bodies is instantaneously equivalent to rotation. In Velocity/Acceleration Analysis, the focus is on relative motion, Kennedy''s theorem, velocity relationships and construction methods.', 'SSD_INSTANTANEOUS_CENTERS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_019_M03_S01', 'Cam displacement diagrams', '1', 'Cam displacement diagrams: Graphs relating follower displacement, velocity, acceleration or related motion variables to cam angle or time. In Cams, the focus is on follower motion laws, rise/dwell/return, simple harmonic/cycloidal/polynomial motion and motion continuity.', 'SSD_CAM_DISPLACEMENT_DIAGRAMS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_019_M04_S01', 'Epicyclic gear trains', '1', 'Epicyclic gear trains: Gear arrangements in which one or more gears rotate about axes that themselves move relative to a fixed frame. In Gears, the focus is on sun, planet, ring and carrier elements; relative motion; speed ratios and torque relationships.', 'SSD_EPICYCLIC_GEAR_TRAINS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_019_M05_S01', 'Friction in machine mechanisms', '1', 'Friction in machine mechanisms: Resistance to relative motion between contacting machine components, affecting forces, power loss, wear and motion. In Friction, the focus is on dry/sliding friction, rolling resistance, friction laws, lubrication effects and efficiency implications.', 'SSD_FRICTION_IN_MACHINE_MECHANISMS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_020_M01_S01', 'Fins', '1', 'Fins: Extended surfaces used to increase heat-transfer area and enhance heat transfer between a solid and an adjoining fluid. In Conduction, the focus is on fin geometry, conduction within the fin, convection boundary condition, efficiency/effectiveness and temperature distribution.', 'SSD_FINS', 'Semantically_Audited', 'Active', '1.0') ON CONFLICT DO NOTHING;